@pytest.mark.parametrize("raw", [
    "1", "12", "1.", "1.25", ".5", "1e2", "1E+2", "1e-2",
    "1.e2", "1.25E-2", ".5e+2",
])
@pytest.mark.parametrize("suffix", ["é", "中", "١", "１", "²"])
@pytest.mark.parametrize("prefix,line,column", [("SELECT ", 1, 8), ("\n\tSELECT ", 2, 9)])
def test_unicode_number_continuation_at_literal_start(raw, suffix, prefix, line, column):
    with pytest.raises(LexError) as caught:
        tokenize(prefix + raw + suffix)
    assert str(caught.value) == (
        f"LexError at line {line}, column {column}: invalid number literal"
    )


@pytest.mark.parametrize("char", ["é", "١", "１"])
@pytest.mark.parametrize("prefix", ["SELECT ", "SELECT a", "SELECT ."])
def test_unicode_continuation_does_not_broaden_ascii_token_starts(char, prefix):
    with pytest.raises(LexError) as caught:
        tokenize(prefix + char)
    assert str(caught.value) == (
        f"LexError at line 1, column {len(prefix) + 1}: unexpected character '{char}'"
    )
